('14eaa9a5d1558180b5b494f7c490e548cbb0dbed3667f3a84c2cd86a082cf761','schema','crm')) SELECT w.id,w.kind, CASE WHEN kind='function' THEN pg_catalog.to_regprocedure(identity)::oid WHEN kind='relation' THEN pg_catalog.to_regclass(identity)::oid WHEN kind='schema' THEN pg_catalog.to_regnamespace(identity)::oid WHEN kind='constraints' THEN (SELECT c.oid FROM pg_catalog.pg_constraint c JOIN pg_catalog.pg_class t ON t.oid=c.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname||'.'||t.relname||'.'||c.conname=w.identity) WHEN kind='default_acl' THEN (SELECT d.oid FROM pg_catalog.pg_default_acl d JOIN pg_catalog.pg_roles r ON r.oid=d.defaclrole JOIN pg_catalog.pg_namespace n ON n.oid=d.defaclnamespace WHERE r.rolname||':'||n.nspname||':'||d.defaclobjtype::text=w.identity) END AS oid, pg_catalog.statement_timestamp() AS observed_at FROM wanted w ORDER BY id